//! Whether Vibe credits itself in commits: a "Generated by Mistral Vibe."
//! line and a Co-Authored-By trailer, unless its config.toml says
//! include_commit_signature = false. Port of
//! internal/adapters/vibe/attribution.go:1-73.

use std::path::Path;

use rush_core::adapter::{self, Attributor, Profile};

use super::Vibe;

const SIGNATURE_KEY: &str = "include_commit_signature";

impl Attributor for Vibe {
    /// Whether p's Vibe credits itself (on, set).
    fn attribution(&self, p: &Profile) -> (bool, bool) {
        let Ok(b) = std::fs::read_to_string(Path::new(&p.dir).join("config.toml")) else {
            return (false, false);
        };
        match top_key(&b, SIGNATURE_KEY) {
            Some((_, v)) => (v == "true", true),
            None => (false, false),
        }
    }

    /// Says whether p's Vibe credits itself. Only its one line changes:
    /// the rest of config.toml, comments and all, stays as it is.
    fn set_attribution(&self, p: &Profile, on: bool) -> adapter::Result<()> {
        let path = Path::new(&p.dir).join("config.toml");
        let text = match std::fs::read_to_string(&path) {
            Ok(t) => t,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => String::new(),
            Err(e) => return Err(Box::new(e)),
        };
        let line = format!("{SIGNATURE_KEY} = {on}");
        let text = match top_key(&text, SIGNATURE_KEY) {
            Some((i, _)) => {
                let mut lines: Vec<&str> = text.split('\n').collect();
                lines[i] = &line;
                lines.join("\n")
            }
            None => format!("{line}\n{text}"), // a top-level key goes before any table
        };
        {
            use std::os::unix::fs::DirBuilderExt;
            std::fs::DirBuilder::new()
                .recursive(true)
                .mode(0o700)
                .create(&p.dir)?;
        }
        let tmp = Path::new(&p.dir).join("config.toml.tmp");
        {
            use std::io::Write;
            use std::os::unix::fs::OpenOptionsExt;
            let mut f = std::fs::OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .mode(0o600)
                .open(&tmp)?;
            f.write_all(text.as_bytes())?;
        }
        std::fs::rename(&tmp, &path)?;
        Ok(())
    }
}

/// Finds key among a TOML file's top-level keys, those before its first
/// table: its line, and its value as written.
fn top_key(text: &str, key: &str) -> Option<(usize, String)> {
    for (i, l) in text.split('\n').enumerate() {
        let t = l.trim();
        if t.starts_with('[') {
            break;
        }
        if let Some((k, v)) = t.split_once('=')
            && k.trim() == key
        {
            let v = v.split('#').next().unwrap_or_default();
            return Some((i, v.trim().to_string()));
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::util::path_str;

    // attribution_test.go: TestAttributionChangesOnlyItsLine
    #[test]
    fn changes_only_its_line() {
        let d = tempfile::tempdir().unwrap();
        let p = Profile {
            dir: path_str(d.path()),
            ..Profile::default()
        };
        let path = d.path().join("config.toml");
        let orig = "# mine\nactive_model = \"devstral\"\n\n[[providers]]\nname = \"mistral\"\ninclude_commit_signature = true\n";
        std::fs::write(&path, orig).unwrap();
        let v = Vibe::without_keychain();
        assert!(
            !v.attribution(&p).1,
            "a key inside a table isn't Vibe's top-level one"
        );
        v.set_attribution(&p, false).unwrap();
        assert_eq!(v.attribution(&p), (false, true));
        v.set_attribution(&p, true).unwrap();
        let b = std::fs::read_to_string(&path).unwrap();
        assert_eq!(b, format!("include_commit_signature = true\n{orig}"));
        assert_eq!(b.matches("include_commit_signature").count(), 2);
    }
}
